</form><script>document.addEventListener('DOMContentLoaded',()=>{const topic=document.getElementById('support-topic');const subject=document.querySelector('input[name="subject"]');const description=document.querySelector('textarea[name="description"]');const type=document.querySelector('select[name="ticket_type"]');const fields={notify_staff_bell:document.querySelector('input[name="notify_staff_bell"]'),notify_staff_sms:document.querySelector('input[name="notify_staff_sms"]'),notify_customer_sms:document.querySelector('input[name="notify_customer_sms"]'),notify_customer_whatsapp:document.querySelector('input[name="notify_customer_whatsapp"]'),notify_owner_telegram:document.querySelector('input[name="notify_owner_telegram"]')};const syncTopics=()=>{const selected=type.value;[...topic.options].forEach(o=>{if(!o.value)return;o.hidden=o.dataset.type && o.dataset.type!==selected;});if(topic.selectedOptions[0]?.hidden)topic.value='';};type.addEventListener('change',syncTopics);topic.addEventListener('change',()=>{const o=topic.options[topic.selectedIndex];if(!o)return;if(o.dataset.type)type.value=o.dataset.type;if(o.dataset.subject && !subject.value)subject.value=o.dataset.subject;if(o.dataset.description && !description.value)description.value=o.dataset.description;const dataMap={notify_staff_bell:'staffBell',notify_staff_sms:'staffSms',notify_customer_sms:'customerSms',notify_customer_whatsapp:'whatsapp',notify_owner_telegram:'telegram'};Object.entries(fields).forEach(([k,el])=>{if(el){const attr={staffBell:'staffBell',staffSms:'staffSms',customerSms:'customerSms',whatsapp:'whatsapp',telegram:'telegram'}[dataMap[k]];el.checked=o.dataset[attr]==='1';}});});syncTopics();});</script></div></div></div>
